  1→<!DOCTYPE html>
  2→<html lang="en">
  3→<head>
  4→  <meta charset="UTF-8">
  5→  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  6→  <title>Topic Segmentation</title>
  7→  <style>
  8→    * { margin: 0; padding: 0; box-sizing: border-box; }
  9→    body {
 10→      font-family: Arial, Helvetica, sans-serif;
 11→      background: white;
 12→      display: flex;
 13→      justify-content: center;
 14→      align-items: center;
 15→      min-height: 100vh;
 16→      padding: 20px;
 17→    }
 18→
 19→    .diagram {
 20→      background: #dce9f5;
 21→      border: 1.5px solid #a0b8d0;
 22→      border-radius: 12px;
 23→      padding: 12px 16px 16px;
 24→      display: flex;
 25→      flex-direction: column;
 26→      align-items: center;
 27→      width: 1660px;
 28→      max-width: 100%;
 29→    }
 30→
 31→    .diagram-title {
 32→      font-size: 18px;
 33→      font-weight: bold;
 34→      color: #222;
 35→      margin-bottom: 8px;
 36→    }
 37→
 38→    .flow {
 39→      display: flex;
 40→      align-items: center;
 41→      gap: 0;
 42→      width: 100%;
 43→    }
 44→
 45→    /* ── Phone mockup ── */
 46→    .phone {
 47→      width: 260px;
 48→      min-width: 260px;
 49→      height: 384px;
 50→      background: white;
 51→      border: 1.2px solid #999;
 52→      border-radius: 10px;
 53→      padding: 10px 16px;
 54→      position: relative;
 55→      display: flex;
 56→      flex-direction: column;
 57→      gap: 4px;
 58→      overflow: hidden;
 59→    }
 60→    .phone .token-badge-top {
 61→      position: absolute;
 62→      top: -15px;
 63→      left: 50%;
 64→      transform: translateX(-50%);
 65→      background: #555;
 66→      color: white;
 67→      font-size: 13px;
 68→      font-weight: bold;
 69→      padding: 2px 14px;
 70→      border-radius: 6px;
 71→    }
 72→    .phone .scrollbar {
 73→      position: absolute;
 74→      right: 5px;
 75→      top: 30px;
 76→      width: 5px;
 77→      height: 50px;
 78→      background: #ccc;
 79→      border-radius: 3px;
 80→    }
 81→    .phone .dots {
 82→      text-align: center;
 83→      color: #999;
 84→      font-size: 18px;
 85→      letter-spacing: 4px;
 86→      margin-top: auto;
 87→    }
 88→
 89→    /* ── Message bubbles ── */
 90→    .user-msg {
 91→      align-self: flex-end;
 92→      background: #d0e0f8;
 93→      border: 0.5px solid #a0c0e8;
 94→      border-radius: 10px;
 95→      height: 20px;
 96→      width: 55%;
 97→      display: flex;
 98→      align-items: center;
 99→      padding: 0 10px;
100→    }
101→    .user-msg .line {
102→      height: 2px;
103→      background: #8ab0d8;
104→      width: 100%;
105→      border-radius: 1px;
106→    }
107→
108→    .ai-msg {
109→      background: #f0f0f0;
110→      border: 0.5px solid #ccc;
111→      border-radius: 14px;
112→      padding: 8px 10px;
113→      display: flex;
114→      flex-direction: column;
115→      gap: 4px;
116→      position: relative;
117→    }
118→    .ai-msg .token-badge {
119→      position: absolute;
120→      top: 4px;
121→      right: 8px;
122→      background: #aaa;
123→      color: white;
124→      font-size: 10px;
125→      padding: 1px 8px;
126→      border-radius: 4px;
127→    }
128→
129→    /* ── Document blocks ── */
130→    .doc {
131→      border-radius: 4px;
132→      padding: 5px 6px;
133→      display: flex;
134→      flex-direction: column;
135→      gap: 3px;
136→      background: white;
137→    }
138→    .doc.large {
139→      border: 1.2px solid #e07050;
140→      min-height: 44px;
141→    }
142→    .doc.medium {
143→      border: 0.7px solid #c0c0c0;
144→      min-height: 26px;
145→    }
146→    .doc.tiny {
147→      border: 0.5px solid #c0c0c0;
148→      min-height: 16px;
149→    }
150→    .doc .text-line {
151→      height: 2px;
152→      border-radius: 1px;
153→    }
154→    .doc .text-line.dark { background: #888; }
155→    .doc .text-line.light { background: #bbb; }
156→    .doc .text-line.w40 { width: 40%; }
157→    .doc .text-line.w50 { width: 50%; }
158→    .doc .text-line.w60 { width: 60%; }
159→    .doc .text-line.w70 { width: 70%; }
160→    .doc .text-line.w80 { width: 80%; }
161→    .doc .text-line.w90 { width: 90%; }
162→    .doc .text-line.w100 { width: 100%; }
163→    .doc .code-block {
164→      width: 55%;
165→      height: 8px;
166→      background: #e2e2e2;
167→      border: 0.3px solid #c8c8c8;
168→      border-radius: 3px;
169→      display: flex;
170→      align-items: center;
171→      padding: 0 4px;
172→    }
173→    .doc .code-block .code-line {
174→      height: 1.5px;
175→      width: 60%;
176→      background: #7a9a6a;
177→      border-radius: 1px;
178→    }
179→
180→    /* ── Arrows ── */
181→    .arrow-right {
182→      display: flex;
183→      align-items: center;
184→      padding: 0 4px;
185→      flex-shrink: 0;
186→    }
187→    .arrow-right .shaft {
188→      height: 2px;
189→      width: 24px;
190→      background: #333;
191→    }
192→    .arrow-right .head {
193→      width: 0;
194→      height: 0;
195→      border-top: 6px solid transparent;
196→      border-bottom: 6px solid transparent;
197→      border-left: 10px solid #333;
198→    }
199→    .arrow-right.big .shaft { width: 36px; height: 3px; }
200→
201→    /* ── Red curved connectors (minimal SVG) ── */
202→    .red-connectors {
203→      width: 60px;
204→      min-width: 60px;
205→      flex-shrink: 0;
206→      position: relative;
207→    }
208→
209→    /* ── Filter section ── */
210→    .filter-section {
211→      display: flex;
212→      flex-direction: column;
213→      align-items: center;
214→      min-width: 220px;
215→      flex-shrink: 0;
216→    }
217→    .filter-section .section-title {
218→      font-size: 14px;
219→      font-weight: bold;
220→      color: #333;
221→      text-align: center;
222→      line-height: 1.3;
223→    }
224→    .filter-section .section-subtitle {
225→      font-size: 13px;
226→      color: #666;
227→      margin-bottom: 6px;
228→    }
229→    .filter-box {
230→      background: white;
231→      border: 1px solid #aaa;
232→      border-radius: 12px;
233→      padding: 10px;
234→      display: flex;
235→      flex-direction: column;
236→      gap: 8px;
237→      width: 220px;
238→    }
239→
240→    /* ── LLM section ── */
241→    .llm-section {
242→      display: flex;
243→      flex-direction: column;
244→      align-items: center;
245→      flex-shrink: 0;
246→      position: relative;
247→    }
248→    .llm-header {
249→      text-align: center;
250→      margin-bottom: 6px;
251→    }
252→    .llm-header .title { font-size: 15px; font-weight: bold; color: #333; }
253→    .llm-header .subtitle { font-size: 13px; color: #666; }
254→
255→    .split-header {
256→      font-size: 15px;
257→      font-weight: bold;
258→      color: #333;
259→      position: absolute;
260→      top: 0;
261→      right: 60px;
262→    }
263→
264→    .lanes {
265→      display: flex;
266→      flex-direction: column;
267→      gap: 10px;
268→      position: relative;
269→      padding-left: 20px;
270→    }
271→
272→    /* Dashed parallel indicator */
273→    .lanes::before {
274→      content: '';
275→      position: absolute;
276→      left: 0;
277→      top: 0;
278→      bottom: 0;
279→      border-left: 1px dashed #999;
280→    }
281→
282→    .lane {
283→      display: flex;
284→      align-items: center;
285→      gap: 6px;
286→    }
287→
288→    .llm-pill {
289→      background: #e8efd8;
290→      border: 1px solid #a0b060;
291→      border-radius: 18px;
292→      padding: 4px 14px;
293→      font-size: 14px;
294→      font-weight: bold;
295→      color: #555;
296→      white-space: nowrap;
297→      flex-shrink: 0;
298→    }
299→
300→    .regex-box {
301→      background: #f8f4e8;
302→      border: 0.8px solid #d4c090;
303→      border-radius: 6px;
304→      padding: 6px 8px;
305→      font-family: 'Courier New', monospace;
306→      font-size: 11px;
307→      color: #777;
308→      white-space: pre;
309→      line-height: 1.5;
310→      flex-shrink: 0;
311→    }
312→
313→    /* ── Segment blocks ── */
314→    .segment-blocks {
315→      display: flex;
316→      gap: 3px;
317→      flex-shrink: 0;
318→    }
319→    .seg-block {
320→      background: white;
321→      border: 1.2px solid #e07050;
322→      border-radius: 4px;
323→      padding: 4px 5px;
324→      display: flex;
325→      flex-direction: column;
326→      gap: 3px;
327→      min-height: 60px;
328→    }
329→    .seg-block .seg-line {
330→      height: 1.5px;
331→      background: #ccc;
332→      border-radius: 1px;
333→    }
334→    .seg-block.narrow { width: 30px; }
335→    .seg-block.medium { width: 42px; }
336→    .seg-block.wide { width: 86px; }
337→
338→    /* ── Chunk blocks (output phone) ── */
339→    .chunk-row {
340→      display: flex;
341→      gap: 3px;
342→    }
343→    .chunk {
344→      background: white;
345→      border: 0.9px solid #999;
346→      border-radius: 3px;
347→      padding: 4px 4px;
348→      display: flex;
349→      flex-direction: column;
350→      gap: 3px;
351→      flex: 1;
352→      min-height: 44px;
353→    }
354→    .chunk .seg-line {
355→      height: 1.5px;
356→      background: #bbb;
357→      border-radius: 1px;
358→    }
359→
360→    /* ── Labels row ── */
361→    .labels {
362→      display: flex;
363→      justify-content: space-between;
364→      width: 100%;
365→      margin-top: 6px;
366→      padding: 0 20px;
367→    }
368→    .labels span {
369→      font-size: 14px;
370→      color: #333;
371→      text-align: center;
372→    }
373→  </style>
374→</head>
375→<body>
376→
377→<div class="diagram">
378→  <div class="diagram-title">Topic Segmentation</div>
379→
380→  <div class="flow">
381→
382→    <!-- ════════ Conversation (input phone) ════════ -->
383→    <div style="display: flex; flex-direction: column; align-items: center;">
384→      <div class="phone">
385→        <div class="token-badge-top">~150k tokens</div>
386→        <div class="scrollbar"></div>
387→
388→        <!-- User msg 1 -->
389→        <div class="user-msg"><div class="line"></div></div>
390→
391→        <!-- AI msg 1 -->
392→        <div class="ai-msg">
393→          <div class="token-badge">~25k tok</div>
394→          <!-- Doc 1: LARGE -->
395→          <div class="doc large">
396→            <div class="text-line dark w50"></div>
397→            <div class="text-line light w90"></div>
398→            <div class="text-line dark w40"></div>
399→            <div class="text-line light w80"></div>
400→          </div>
401→          <!-- Doc 2: MEDIUM -->
402→          <div class="doc medium">
403→            <div class="text-line dark w50"></div>
404→            <div class="text-line light w70"></div>
405→          </div>
406→        </div>
407→
408→        <!-- User msg 2 -->
409→        <div class="user-msg"><div class="line"></div></div>
410→
411→        <!-- AI msg 2 -->
412→        <div class="ai-msg">
413→          <div class="token-badge">~40k tok</div>
414→          <!-- Doc 3: LARGE -->
415→          <div class="doc large">
416→            <div class="text-line dark w50"></div>
417→            <div class="text-line light w90"></div>
418→            <div class="text-line dark w40"></div>
419→            <div class="text-line light w70"></div>
420→          </div>
421→          <!-- Doc 4: TINY -->
422→          <div class="doc tiny">
423→            <div class="text-line light w60"></div>
424→          </div>
425→          <!-- Doc 5: LARGE -->
426→          <div class="doc large">
427→            <div class="text-line dark w50"></div>
428→            <div class="text-line light w80"></div>
429→            <div class="text-line dark w40"></div>
430→            <div class="code-block"><div class="code-line"></div></div>
431→          </div>
432→        </div>
433→
434→        <!-- User msg 3 -->
435→        <div class="user-msg"><div class="line"></div></div>
436→
437→        <div class="dots">...</div>
438→      </div>
439→      <span style="font-size:14px; color:#333; margin-top:6px;">Conversation</span>
440→    </div>
441→
442→    <!-- ════════ Red curved arrows (SVG connector) ════════ -->
443→    <div class="red-connectors">
444→      <svg width="60" height="384" viewBox="0 0 60 384" fill="none" xmlns="http://www.w3.org/2000/svg">
445→        <defs>
446→          <marker id="ar" markerWidth="8" markerHeight="6" refX="8" refY="3" orient="auto">
447→            <polygon points="0 0, 8 3, 0 6" fill="#c05030"/>
448→          </marker>
449→        </defs>
450→        <!-- Arrow 1: doc1 → filter part 1 -->
451→        <path d="M 0,72 C 30,72 30,82 58,82" stroke="#c05030" stroke-width="1.5" marker-end="url(#ar)"/>
452→        <!-- Arrow 2: doc3 → filter part 2 -->
453→        <path d="M 0,200 C 30,200 30,140 58,140" stroke="#c05030" stroke-width="1.5" marker-end="url(#ar)"/>
454→        <!-- Arrow 3: doc5 → filter part 3 -->
455→        <path d="M 0,290 C 30,290 30,198 58,198" stroke="#c05030" stroke-width="1.5" marker-end="url(#ar)"/>
456→      </svg>
457→    </div>
458→
459→    <!-- ════════ Filter Large Message Parts ════════ -->
460→    <div class="filter-section">
461→      <div class="section-title">Filter Large<br>Message Parts</div>
462→      <div class="section-subtitle">by Token Count</div>
463→      <div class="filter-box">
464→        <!-- Filtered part 1 -->
465→        <div class="doc large">
466→          <div class="text-line dark w50"></div>
467→          <div class="text-line light w90"></div>
468→          <div class="text-line dark w40"></div>
469→          <div class="text-line light w80"></div>
470→        </div>
471→        <!-- Filtered part 2 -->
472→        <div class="doc large">
473→          <div class="text-line dark w50"></div>
474→          <div class="text-line light w90"></div>
475→          <div class="text-line dark w40"></div>
476→          <div class="text-line light w70"></div>
477→        </div>
478→        <!-- Filtered part 3 -->
479→        <div class="doc large">
480→          <div class="text-line dark w50"></div>
481→          <div class="text-line light w80"></div>
482→          <div class="text-line dark w40"></div>
483→          <div class="code-block"><div class="code-line"></div></div>
484→        </div>
485→      </div>
486→    </div>
487→
488→    <!-- ════════ Arrow: Filter → LLM ════════ -->
489→    <div style="display: flex; flex-direction: column; gap: 56px; padding: 30px 0; align-self: center;">
490→      <div class="arrow-right"><div class="shaft"></div><div class="head"></div></div>
491→      <div class="arrow-right"><div class="shaft"></div><div class="head"></div></div>
492→      <div class="arrow-right"><div class="shaft"></div><div class="head"></div></div>
493→    </div>
494→
495→    <!-- ════════ LLM Detection + Split ════════ -->
496→    <div class="llm-section">
497→      <div style="display: flex; gap: 140px; margin-bottom: 6px; width: 100%; justify-content: center;">
498→        <div class="llm-header">
499→          <div class="title">LLM Boundary Detection</div>
500→          <div class="subtitle">(parallel)</div>
501→        </div>
502→        <div class="llm-header">
503→          <div class="title">Split</div>
504→        </div>
505→      </div>
506→
507→      <div class="lanes">
508→        <!-- Lane 1: splits into 5 -->
509→        <div class="lane">
510→          <div class="llm-pill">LLM</div>
511→          <div class="arrow-right"><div class="shaft" style="width:12px;"></div><div class="head"></div></div>
512→          <div class="regex-box">["(?=## Setup)",
513→ "(?=```\n)",
514→ "(?=## Impl)",
515→ "(?=Step 4:)"]</div>
516→          <div class="arrow-right"><div class="shaft" style="width:12px;"></div><div class="head"></div></div>
517→          <div class="segment-blocks">
518→            <div class="seg-block narrow">
519→              <div class="seg-line" style="width:80%;"></div>
520→              <div class="seg-line" style="width:60%;"></div>
521→              <div class="seg-line" style="width:80%;"></div>
522→              <div class="seg-line" style="width:55%;"></div>
523→            </div>
524→            <div class="seg-block narrow">
525→              <div class="seg-line" style="width:80%;"></div>
526→              <div class="seg-line" style="width:60%;"></div>
527→              <div class="seg-line" style="width:80%;"></div>
528→            </div>
529→            <div class="seg-block narrow">
530→              <div class="seg-line" style="width:80%;"></div>
531→              <div class="seg-line" style="width:55%;"></div>
532→            </div>
533→            <div class="seg-block narrow">
534→              <div class="seg-line" style="width:80%;"></div>
535→              <div class="seg-line" style="width:60%;"></div>
536→              <div class="seg-line" style="width:80%;"></div>
537→              <div class="seg-line" style="width:55%;"></div>
538→            </div>
539→            <div class="seg-block narrow">
540→              <div class="seg-line" style="width:80%;"></div>
541→              <div class="seg-line" style="width:60%;"></div>
542→              <div class="seg-line" style="width:80%;"></div>
543→            </div>
544→          </div>
545→        </div>
546→
547→        <!-- Lane 2: splits into 2 -->
548→        <div class="lane">
549→          <div class="llm-pill">LLM</div>
550→          <div class="arrow-right"><div class="shaft" style="width:12px;"></div><div class="head"></div></div>
551→          <div class="regex-box">["(?=Now let's)"]</div>
552→          <div class="arrow-right"><div class="shaft" style="width:12px;"></div><div class="head"></div></div>
553→          <div class="segment-blocks">
554→            <div class="seg-block wide">
555→              <div class="seg-line" style="width:85%;"></div>
556→              <div class="seg-line" style="width:70%;"></div>
557→              <div class="seg-line" style="width:85%;"></div>
558→              <div class="seg-line" style="width:55%;"></div>
559→              <div class="seg-line" style="width:75%;"></div>
560→            </div>
561→            <div class="seg-block wide">
562→              <div class="seg-line" style="width:85%;"></div>
563→              <div class="seg-line" style="width:70%;"></div>
564→              <div class="seg-line" style="width:85%;"></div>
565→              <div class="seg-line" style="width:55%;"></div>
566→            </div>
567→          </div>
568→        </div>
569→
570→        <!-- Lane 3: splits into 3 -->
571→        <div class="lane">
572→          <div class="llm-pill">LLM</div>
573→          <div class="arrow-right"><div class="shaft" style="width:12px;"></div><div class="head"></div></div>
574→          <div class="regex-box">["(?=## Review)",
575→ "(?=Finally,)"]</div>
576→          <div class="arrow-right"><div class="shaft" style="width:12px;"></div><div class="head"></div></div>
577→          <div class="segment-blocks">
578→            <div class="seg-block medium">
579→              <div class="seg-line" style="width:85%;"></div>
580→              <div class="seg-line" style="width:65%;"></div>
581→              <div class="seg-line" style="width:85%;"></div>
582→              <div class="seg-line" style="width:55%;"></div>
583→            </div>
584→            <div class="seg-block medium">
585→              <div class="seg-line" style="width:85%;"></div>
586→              <div class="seg-line" style="width:65%;"></div>
587→              <div class="seg-line" style="width:85%;"></div>
588→            </div>
589→            <div class="seg-block medium">
590→              <div class="seg-line" style="width:85%;"></div>
591→              <div class="seg-line" style="width:65%;"></div>
592→            </div>
593→          </div>
594→        </div>
595→      </div>
596→      <span style="font-size:14px; color:#333; margin-top:8px;">Segments</span>
597→    </div>
598→
599→    <!-- ════════ Arrow: Split → Output ════════ -->
600→    <div class="arrow-right big" style="margin: 0 8px;">
601→      <div class="shaft"></div>
602→      <div class="head"></div>
603→    </div>
604→
605→    <!-- ════════ Segmented Conversation (output phone) ════════ -->
606→    <div style="display: flex; flex-direction: column; align-items: center;">
607→      <div class="phone">
608→
609→        <!-- User msg 1 -->
610→        <div class="user-msg"><div class="line"></div></div>
611→
612→        <!-- AI msg 1 -->
613→        <div class="ai-msg">
614→          <div class="token-badge">~25k tok</div>
615→          <!-- Doc 1: 5 chunks -->
616→          <div class="chunk-row">
617→            <div class="chunk">
618→              <div class="seg-line" style="width:80%; height:1.5px; background:#bbb;"></div>
619→              <div class="seg-line" style="width:60%; height:1.5px; background:#bbb;"></div>
620→            </div>
621→            <div class="chunk">
622→              <div class="seg-line" style="width:80%; height:1.5px; background:#bbb;"></div>
623→              <div class="seg-line" style="width:60%; height:1.5px; background:#bbb;"></div>
624→              <div class="seg-line" style="width:80%; height:1.5px; background:#bbb;"></div>
