632→<script>
633→document.addEventListener('DOMContentLoaded', () => {
634→  const flow = document.querySelector('.flow');
635→  const flowRect = flow.getBoundingClientRect();
636→
637→  // Create SVG overlay
638→  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
639→  svg.classList.add('arrow-overlay');
640→  svg.setAttribute('width', flowRect.width);
641→  svg.setAttribute('height', flowRect.height);
642→  svg.setAttribute('viewBox', `0 0 ${flowRect.width} ${flowRect.height}`);
643→
644→  // Arrow marker
645→  const defs = document.createElementNS('http://www.w3.org/2000/svg', 'defs');
646→  const marker = document.createElementNS('http://www.w3.org/2000/svg', 'marker');
647→  marker.setAttribute('id', 'ar');
648→  marker.setAttribute('markerWidth', '8');
649→  marker.setAttribute('markerHeight', '6');
650→  marker.setAttribute('refX', '8');
651→  marker.setAttribute('refY', '3');
652→  marker.setAttribute('orient', 'auto');
653→  const poly = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
654→  poly.setAttribute('points', '0 0, 8 3, 0 6');
655→  poly.setAttribute('fill', '#c05030');
656→  marker.appendChild(poly);
657→  defs.appendChild(marker);
658→  svg.appendChild(defs);
659→
660→  // Draw curved arrow for each pair
661→  for (let i = 1; i <= 3; i++) {
662→    const src = document.querySelector(`[data-src="${i}"]`);
663→    const dst = document.querySelector(`[data-dst="${i}"]`);
664→    const srcR = src.getBoundingClientRect();
665→    const dstR = dst.getBoundingClientRect();
666→
667→    const x1 = srcR.right - flowRect.left;
668→    const y1 = srcR.top + srcR.height / 2 - flowRect.top;
669→    const x2 = dstR.left - flowRect.left;
670→    const y2 = dstR.top + dstR.height / 2 - flowRect.top;
671→
672→    const cpx = (x1 + x2) / 2;
673→
674→    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
675→    path.setAttribute('d', `M ${x1},${y1} C ${cpx},${y1} ${cpx},${y2} ${x2},${y2}`);
676→    path.setAttribute('fill', 'none');
677→    path.setAttribute('stroke', '#c05030');
678→    path.setAttribute('stroke-width', '1.5');
679→    path.setAttribute('marker-end', 'url(#ar)');
680→    svg.appendChild(path);
681→  }
682→
683→  flow.appendChild(svg);
684→});
685→</script>
