613→              <div class="seg-line" style="width:65%; height:1.5px; background:#bbb;"></div>
614→            </div>
615→            <div class="chunk">
616→              <div class="seg-line" style="width:80%; height:1.5px; background:#bbb;"></div>
617→              <div class="seg-line" style="width:65%; height:1.5px; background:#bbb;"></div>
618→              <div class="seg-line" style="width:80%; height:1.5px; background:#bbb;"></div>
619→            </div>
620→          </div>
621→        </div>
622→
623→        <!-- User msg 3 -->
624→        <div class="user-msg"><div class="line"></div></div>
625→
626→        <div class="dots">...</div>
627→      </div>
628→      <div style="font-size:14px; color:#333; margin-top:6px; text-align:center;">Segmented<br>Conversation</div>
629→    </div>
630→
631→  </div><!-- /flow -->
632→</div><!-- /diagram -->
633→
634→<script>
635→document.addEventListener('DOMContentLoaded', () => {
636→  const flow = document.querySelector('.flow');
637→  const flowRect = flow.getBoundingClientRect();
638→
639→  // Create SVG overlay
640→  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
641→  svg.classList.add('arrow-overlay');
642→  svg.setAttribute('width', flowRect.width);
643→  svg.setAttribute('height', flowRect.height);
644→  svg.setAttribute('viewBox', `0 0 ${flowRect.width} ${flowRect.height}`);
645→
646→  // Arrow marker
647→  const defs = document.createElementNS('http://www.w3.org/2000/svg', 'defs');
648→  const marker = document.createElementNS('http://www.w3.org/2000/svg', 'marker');
649→  marker.setAttribute('id', 'ar');
650→  marker.setAttribute('markerWidth', '8');
651→  marker.setAttribute('markerHeight', '6');
652→  marker.setAttribute('refX', '8');
653→  marker.setAttribute('refY', '3');
654→  marker.setAttribute('orient', 'auto');
655→  const poly = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
656→  poly.setAttribute('points', '0 0, 8 3, 0 6');
657→  poly.setAttribute('fill', '#c05030');
658→  marker.appendChild(poly);
659→  defs.appendChild(marker);
660→  svg.appendChild(defs);
661→
662→  // Draw curved arrow for each pair
663→  for (let i = 1; i <= 3; i++) {
664→    const src = document.querySelector(`[data-src="${i}"]`);
665→    const dst = document.querySelector(`[data-dst="${i}"]`);
666→    const srcR = src.getBoundingClientRect();
667→    const dstR = dst.getBoundingClientRect();
668→
669→    const x1 = srcR.right - flowRect.left;
670→    const y1 = srcR.top + srcR.height / 2 - flowRect.top;
671→    const x2 = dstR.left - flowRect.left;
672→    const y2 = dstR.top + dstR.height / 2 - flowRect.top;
673→
674→    const cpx = (x1 + x2) / 2;
675→
676→    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
677→    path.setAttribute('d', `M ${x1},${y1} C ${cpx},${y1} ${cpx},${y2} ${x2},${y2}`);
678→    path.setAttribute('fill', 'none');
679→    path.setAttribute('stroke', '#c05030');
680→    path.setAttribute('stroke-width', '1.5');
681→    path.setAttribute('marker-end', 'url(#ar)');
682→    svg.appendChild(path);
683→  }
684→
685→  flow.appendChild(svg);
686→});
687→</script>
