  font-size: 8px;
  color: #777;
  font-family: 'Courier New', monospace;
  padding: 2px 4px;
  border-radius: 3px;
  background: #f8f8f8;
  border: 0.5px solid #ddd;
}
.part-row .part-id {
  color: #999;
  font-size: 7px;
  min-width: 18px;
}
.part-row .part-role {
  font-size: 7px;
  padding: 0 3px;
  border-radius: 2px;
  color: white;
}
.part-role.user { background: #6a9fd8; }
.part-role.asst { background: #aaa; }
.part-role.tool { background: #c0a060; }

/* Batch bracket */
.batch-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.batch {
  background: white;
  border: 1px solid #aaa;
  border-radius: 8px;
  padding: 6px 8px;
  display: flex;
  align-items: center;
  gap: 4px;
}
.batch-label {
  font-size: 8px;
  color: #999;
  writing-mode: vertical-lr;
  transform: rotate(180deg);
  letter-spacing: 1px;
  text-transform: uppercase;
  font-weight: bold;
}
.batch-parts {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.batch-part {
  height: 3px;
  border-radius: 1px;
  background: #ccc;
}

/* Mapping output */
.mapping-box {
  background: white;
  border: 1px solid #aaa;
  border-radius: 8px;
  padding: 8px;
  font-family: 'Courier New', monospace;
  font-size: 9px;
  color: #555;
  line-height: 1.6;
}
.mapping-row {
  display: flex;
  gap: 4px;
}
.mapping-row .m-id { color: #999; }
.mapping-row .m-arrow { color: #aaa; }
.mapping-row .m-comp { font-weight: bold; }

/* Components input (side label fed into LLM) */
.components-input {
  background: #e8efd8;
  border: 1px solid #a0b060;
  border-radius: 6px;
  padding: 4px 6px;
  font-family: 'Courier New', monospace;
  font-size: 8px;
  color: #555;
  line-height: 1.5;
  white-space: nowrap;
}
.components-input .ci-title {
  font-size: 9px;
  font-weight: bold;
  color: #6a8030;
  margin-bottom: 2px;
}

